<section class="panel"><div class="panel-title"><div><h2>DNS-Einträge</h2><p>Zone: <?= e($service['meta']['zone']) ?></p></div><form method="post"><?= csrf() ?><input type="hidden" name="action" value="dns_refresh"><input type="hidden" name="service_id" value="<?= $service['id'] ?>"><button class="button button-outline button-small">Zone veröffentlichen</button></form></div><div class="table-scroll"><table><thead><tr><th>Typ</th><th>Name</th><th>Ziel</th><th>TTL</th><th></th></tr></thead><tbody><?php foreach($records as $r): ?><tr><td><strong><?= e($r['fieldType']) ?></strong></td><td><?= e($r['subDomain']?:'@') ?></td><td class="dns-target"><?= e($r['target']) ?></td><td><?= (int)$r['ttl'] ?></td><td><?php if(in_array($r['fieldType'],['A','AAAA','CNAME','MX','TXT','SRV','CAA','NS'],true)): ?><a class="text-link" href="/konto/verwalten?id=<?= $service['id'] ?>&amp;eintrag=<?= (int)$r['id'] ?>#dns-form">Ändern</a><?php if($r['fieldType']!=='NS'): ?><form method="post" class="inline-delete" data-confirm="Diesen DNS-Eintrag löschen? Website, E-Mail oder andere Dienste können dadurch ausfallen."><?= csrf() ?><input type="hidden" name="action" value="dns_delete"><input type="hidden" name="service_id" value="<?= $service['id'] ?>"><input type="hidden" name="record_id" value="<?= (int)$r['id'] ?>"><button class="text-button">Löschen</button></form><?php endif ?><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel form-panel" id="dns-form"><h2><?= $edit?'DNS-Eintrag ändern':'DNS-Eintrag hinzufügen' ?></h2><form method="post"><?= csrf() ?><input type="hidden" name="action" value="<?= $edit?'dns_update':'dns_create' ?>"><input type="hidden" name="service_id" value="<?= $service['id'] ?>"><?php if($edit): ?><input type="hidden" name="record_id" value="<?= (int)$edit['id'] ?>"><?php endif ?><div class="form-grid"><label class="field"><span>Typ</span><select name="type" <?= $edit?'disabled':'' ?>><?php foreach(['A','AAAA','CNAME','MX','TXT','SRV','CAA','NS'] as $type): ?><option value="<?= $type ?>" <?= ($edit['fieldType']??$_POST['type']??'A')===$type?'selected':'' ?>><?= $type ?></option><?php endforeach ?></select><?php if($edit): ?><input type="hidden" name="type" value="<?= e($edit['fieldType']) ?>"><?php endif ?></label><label class="field"><span>Host / Subdomain</span><input name="subdomain" maxlength="253" placeholder="@ oder www" value="<?= e($edit['subDomain']??$_POST['subdomain']??'') ?>"></label></div><label class="field"><span>Ziel</span><input name="target" maxlength="2048" required value="<?= e($edit['target']??$_POST['target']??'') ?>"><small>A: IPv4 · AAAA: IPv6 · MX: Priorität und Mailserver · TXT: Textinhalt</small></label><label class="field"><span>TTL in Sekunden</span><input name="ttl" type="number" min="60" max="86400" value="<?= (int)($edit['ttl']??$_POST['ttl']??3600) ?>" required></label><label class="checkbox-field"><input type="checkbox" name="nameserver_confirm" value="1" <?= ($edit['fieldType']??'')==='NS'?'required':'' ?>><span>Bei Typ NS: Ich beauftrage die Änderung dieses Nameserver-Eintrags ausdrücklich.</span></label><button class="button button-teal">Speichern & veröffentlichen <?= icon('check') ?></button><?php if($edit): ?> <a class="text-link" href="/konto/verwalten?id=<?= $service['id'] ?>">Abbrechen</a><?php endif ?></form><?php if(($edit['fieldType']??'')==='NS'): ?><details class="credential-change"><summary>NS-Eintrag entfernen</summary><form method="post" data-confirm="Diesen NS-Eintrag wirklich entfernen? Prüfe zuvor, dass die zuständigen Nameserver korrekt hinterlegt sind."><?= csrf() ?><input type="hidden" name="action" value="dns_delete"><input type="hidden" name="service_id" value="<?= (int)$service['id'] ?>"><input type="hidden" name="record_id" value="<?= (int)$edit['id'] ?>"><label class="checkbox-field"><input type="checkbox" name="nameserver_confirm" value="1" required><span>Ich beauftrage die Löschung dieses NS-Eintrags ausdrücklich.</span></label><button class="text-button">NS-Eintrag löschen</button></form></details><?php endif ?></section><p class="small muted">DNS-Änderungen wirken sich auf deine Dienste aus. Die Einrichtung ändert deine bisherigen NS-Einträge und die Nameserver-Delegation nicht. NS-Einträge kannst du hier anschließend manuell bearbeiten. Ein Wechsel der Nameserver für die gesamte Domain muss zusätzlich beim Domainanbieter beauftragt werden.</p>
<?php endif ?>
<?php elseif($service['provider']==='proxmox'):$vm=null;try{$api=new ProxmoxProvider();if(!$api->poolContains($service['meta']['node'],(int)$service['meta']['vmid'],proxmox_service_type($service)))throw new RuntimeException('Die VM ist nicht im zugeordneten Shop-Pool. Bitte den Support kontaktieren.');$vm=$api->vm($service['meta']['node'],(int)$service['meta']['vmid'],proxmox_service_type($service));}catch(RuntimeException $ex){$resourceError=$ex->getMessage();} ?>
<?php if($resourceError): ?><div class="info-box"><?= icon('server') ?><span><?= e($resourceError) ?></span></div><?php else: ?><section class="panel form-panel"><div class="panel-title"><h2><?= e($vm['name']??$vm['hostname']??$service['identifier']) ?></h2><?= badge(($vm['status']??'')==='running'?'active':'suspended') ?></div><dl class="detail-list"><div><dt>VMID / Node</dt><dd><?= (int)$service['meta']['vmid'] ?> / <?= e($service['meta']['node']) ?></dd></div><div><dt>CPU</dt><dd><?= (int)($vm['cpus']??0) ?> vCPU</dd></div><div><dt>Arbeitsspeicher</dt><dd><?= round(($vm['maxmem']??0)/1073741824,1) ?> GB</dd></div><div><dt>Aktuelle RAM-Nutzung</dt><dd><?= round(($vm['mem']??0)/1073741824,2) ?> GB</dd></div><div><dt>Laufzeit</dt><dd><?= floor(($vm['uptime']??0)/3600) ?> Stunden</dd></div></dl><div class="button-row"><?php foreach(['start'=>'Starten','shutdown'=>'Herunterfahren','stop'=>'Stoppen','reboot'=>'Neu starten'] as $command=>$caption): ?><form method="post" <?= $command!=='start'?'data-confirm="Diese Serveraktion jetzt ausführen? Laufende Anwendungen können unterbrochen werden."':'' ?>><?= csrf() ?><input type="hidden" name="action" value="vps_control"><input type="hidden" name="service_id" value="<?= $service['id'] ?>"><input type="hidden" name="command" value="<?= $command ?>"><button class="button <?= $command==='start'?'button-teal':'button-outline' ?> button-small"><?= $caption ?></button></form><?php endforeach ?></div></section><?php endif ?>
<?php elseif($service['provider']==='ispconfig'):$site=null;try{$site=hosting_site($service,new IspconfigProvider());}catch(RuntimeException $ex){$resourceError=$ex->getMessage();} ?>
<?php if($resourceError): ?><div class="info-box"><?= icon('package') ?><span><?= e($resourceError) ?></span></div><?php else: ?><section class="panel form-panel"><h2>Dein Webspace</h2><dl class="detail-list"><div><dt>Domain</dt><dd><?= e($site['domain']) ?></dd></div><div><dt>Speicherplatz</dt><dd><?= (int)$site['hd_quota'] ?> MB</dd></div><div><dt>PHP</dt><dd><?= e($site['php']) ?></dd></div><div><dt>SSL</dt><dd><?= ($site['ssl']??'n')==='y'?'Aktiv':'Noch nicht aktiv' ?></dd></div><div><dt>FTP / Datenbanken / Postfächer</dt><dd><?= (int)$service['meta']['limits']['ftp'] ?> / <?= (int)$service['meta']['limits']['database'] ?> / <?= (int)$service['meta']['limits']['mail'] ?></dd></div></dl></section>
<?php require __DIR__.'/hosting-management.php'; ?><?php hosting_cron_panel($service); ?><?php endif ?>
<?php endif;endif ?>
